// Real Opus decode capability, established by decoding actual Opus/WebM bytes
// rather than by asking an advisory API.
//
// Two clips are probed, and the PAIR of results is what matters:
//
//   multichannel OK               -> everything this player needs works
//   multichannel FAILS, stereo OK -> the browser decodes Opus but not beyond
//                                    2 channels. Seen in the wild on Chrome:
//                                    the DirectOpusAudioDecoding field trial
//                                    (server-delivered, at EnabledLaunch as of
//                                    2026-08-16, absent from chrome://flags)
//                                    breaks every channel count above 2 in
//                                    BOTH decodeAudioData and MSE, while
//                                    leaving stereo working. Diagnosing that
//                                    from the outside is unreasonable, so the
//                                    player names it and gives the flag that
//                                    restores it.
//   both FAIL                     -> no usable Opus/WebM decode at all. Safari
//                                    27 is here: WebKit has a long history of
//                                    MediaSource.isTypeSupported() answering
//                                    true for audio/webm; codecs="opus" while
//                                    the decode still fails (webkit.org bugs
//                                    238546, 245428, 226922), which is exactly
//                                    why this module decodes real bytes rather
//                                    than trusting isTypeSupported.
//
// decodeAudioData on an OfflineAudioContext needs no user gesture, no
// MediaSource and no SourceBuffer, so it can run at page load and cannot be
// fooled by an advisory API. The multichannel clip is 25-channel (4th-order
// Ambisonics, mapping_family 255), the highest this player supports: decoding
// more channels is strictly harder than fewer, so one pass covers 16 and 2 as
// well. Both clips are embedded as base64 so the probe is self-contained and
// does not depend on where this bundle is deployed from.
//
// Cost: about 85 KB of base64 in the bundle. That buys a correct verdict plus
// an actionable message instead of a stuck spinner.
const OPUS_25CH_B64 =
    '';
const OPUS_2CH_B64 =
    '';

// Where the "your Chrome is broken" message sends people for the evidence,
// the workaround and why the usual isolation steps (incognito, guest profile,
// restarting the browser) do not help.
export const CHROME_OPUS_HELP_URL =
    'https://github.com/mormegil6/ambisonic-box/blob/main/docs/CHROME-MULTICHANNEL-OPUS.md';

function base64ToArrayBuffer(b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
}

// Resolves true/false, never rejects. 8 s timeout so a hung decode cannot hang
// player startup.
function decodes(b64) {
    return new Promise((resolve) => {
        const Ctx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
        if (!Ctx) { resolve(false); return; }
        let settled = false;
        const finish = (ok) => { if (!settled) { settled = true; resolve(ok); } };
        const timer = setTimeout(() => finish(false), 8000);
        try {
            const ctx = new Ctx(1, 1, 48000);
            // Callback form, not the promise form: Safari was late to support
            // the promise form, and the callback form works everywhere. Also
            // avoids an unhandled rejection on the failure path.
            ctx.decodeAudioData(
                base64ToArrayBuffer(b64),
                () => { clearTimeout(timer); finish(true); },
                () => { clearTimeout(timer); finish(false); }
            );
        } catch (e) {
            clearTimeout(timer);
            finish(false);
        }
    });
}

// -> { ok, multichannel, stereo, diagnosis }
// diagnosis: 'ok' | 'multichannel-only-failure' | 'no-opus'
export async function probeOpusSupport() {
    const multichannel = await decodes(OPUS_25CH_B64);
    if (multichannel) {
        return { ok: true, multichannel: true, stereo: true, diagnosis: 'ok' };
    }
    // Only reached on failure, so the extra decode costs nothing in the
    // common case. It is what separates "this browser cannot do Opus" from
    // "this browser cannot do Opus BEYOND STEREO", which need different advice.
    const stereo = await decodes(OPUS_2CH_B64);
    return {
        ok: false,
        multichannel: false,
        stereo: stereo,
        diagnosis: stereo ? 'multichannel-only-failure' : 'no-opus',
    };
}
